export function generateOrigin(s,mix,areaSalt=0){const key=`${s.lifeId||s.seed}:${s.seed}:${areaSalt}`,pool=SETTINGS.filter(x=>x.home===s.home),base=pool[mix(key,40)%pool.length],bed=BEDDING[s.home][mix(key,41)%8],care=CARE[mix(key,42)%8],sound=SOUND[mix(key,43)%8],food=FOOD[mix(key,44)%6],access=ACCESS[mix(key,45)%6],mother=!(base.space==='foster'&&mix(key,46)%3===0),support=(s.home==='family'?30:s.home==='shelter'?25:5)+mix(key,47)%(s.home==='street'?66:66),resources=(s.home==='family'?40:s.home==='shelter'?35:10)+mix(key,48)%(s.home==='family'?56:s.home==='shelter'?61:76),noise=10+mix(key,49)%81;const factors={setting:base.id,bedding:bed,careSchedule:care,soundscape:sound,foodPattern:food,access,mother,support,resources,noise};return {...base,id:base.id,mother,support,food:resources,sound:noise,factors,story:`${access} 자리. ${bed} 위에 몸을 두고 있다. ${sound} 곳이며, ${care} ${mother?'돌봄의 기척이 어미 곁에 이어진다.':'사람의 손길에 의지한다.'} 먹이 여건은 ${food} 편이다.`};}
